import numpy as np,pandas as pd,time
from sklearn.model_selection import KFold,cross_val_predict
from sklearn.metrics import mean_squared_error
from sklearn.ensemble import ExtraTreesRegressor,RandomForestRegressor,HistGradientBoostingRegressor,GradientBoostingRegressor
from sklearn.neighbors import KNeighborsRegressor
from sklearn.pipeline import make_pipeline
from sklearn.preprocessing import FunctionTransformer,StandardScaler
from sklearn.svm import SVR
from catboost import CatBoostRegressor
tr=pd.read_csv('b3_te_zt900_train.csv');p=pd.read_csv('b3_te_zt900_pool.csv');X=tr.drop(columns='target');y=tr.target.to_numpy();P=p[X.columns]
cv=list(KFold(5,shuffle=True,random_state=42).split(X))
models={}
for k in [2,3,5,8]:
 for power in [1,.5,.25]:models[f'knn{k}_pow{power}']=make_pipeline(FunctionTransformer(lambda a,power=power:a**power),KNeighborsRegressor(k,weights='distance'))
for leaf in [1,2,4]:
 models[f'extra{leaf}']=ExtraTreesRegressor(n_estimators=500,min_samples_leaf=leaf,max_features=1.,random_state=42,n_jobs=4)
 models[f'rf{leaf}']=RandomForestRegressor(n_estimators=500,min_samples_leaf=leaf,max_features=1.,random_state=42,n_jobs=4)
for depth in [3,4,5,6,7]:models[f'cat{depth}']=CatBoostRegressor(iterations=1200,depth=depth,learning_rate=.035,l2_leaf_reg=3,verbose=False,thread_count=4,random_seed=42,allow_writing_files=False)
for power in [1,.5,.25]:
 for C in [1,10,100]:models[f'svr{power}_{C}']=make_pipeline(FunctionTransformer(lambda a,power=power:a**power),SVR(C=C,epsilon=.05,gamma=1))
outs={}; preds={}
for name,model in models.items():
 start=time.time();oof=cross_val_predict(model,X,y,cv=cv);model.fit(X,y);pr=model.predict(P);outs[name]=oof;preds[name]=pr
 rmse=mean_squared_error(y,oof)**.5;mae=np.mean(abs(y-oof));hi=mean_squared_error(y[y>1],oof[y>1])**.5
 ids=np.argsort(pr)[-10:][::-1];print(f'{name} RMSE {rmse:.4f} MAE {mae:.4f} HI {hi:.4f} {time.time()-start:.1f}s: '+', '.join(f'{p.candidate_id[i]}={pr[i]:.3f}' for i in ids),flush=True)
np.savez('/tmp/zt_models.npz',**{f'oof_{k}':v for k,v in outs.items()},**{f'pool_{k}':v for k,v in preds.items()})
