import pandas as pd,numpy as np
from sklearn.metrics.pairwise import euclidean_distances
from sklearn.model_selection import KFold
tr=pd.read_csv('b3_te_zt900_train.csv'); p=pd.read_csv('b3_te_zt900_pool.csv');X=tr.iloc[:,:-1].to_numpy();y=tr.target.to_numpy();P=p.iloc[:,1:].to_numpy();cv=list(KFold(5,shuffle=True,random_state=42).split(X));out=[];saved={}
def pred(X,y,P,k,alpha):
 d=euclidean_distances(P,X);out=[]
 for z,dd in zip(P,d):
  idx=np.argsort(dd)[:k];dist=dd[idx];xx=X[idx];yy=y[idx];weights=1/(dist+.0001);weights/=weights.sum();mu=weights@xx;my=weights@yy
  V=(xx-mu)*np.sqrt(weights)[:,None];b=(yy-my)*np.sqrt(weights);s=max(np.sum((xx-mu)**2*weights[:,None]),1e-8)
  coef=np.linalg.solve(V.T@V+np.eye(X.shape[1])*alpha*s,V.T@b)
  out.append(np.clip(my+(z-mu)@coef, yy.min()-.3, yy.max()+.3))
 return np.array(out)
for pow in [1,.5,.25]:
 for k in [3,5,8,12,20,35]:
  for a in [.0001,.001,.01,.1,1]:
   xx=X**pow;pp=P**pow;oof=np.zeros(len(y))
   for t,v in cv:oof[v]=pred(xx[t],y[t],xx[v],k,a)
   pr=pred(xx,y,pp,k,a);rmse=np.mean((y-oof)**2)**.5;hi=np.mean((y[y>1]-oof[y>1])**2)**.5
   name=f'local_{pow}_{k}_{a}';out.append((rmse,hi,name,pr));saved['oof_'+name]=oof;saved['pool_'+name]=pr
for rmse,hi,name,pr in sorted(out,key=lambda t:t[0])[:20]:
 ids=np.argsort(pr)[-10:][::-1];print(f'{name} RMSE {rmse:.4f} HI {hi:.4f}: '+', '.join(f'{p.candidate_id[i]}={pr[i]:.3f}' for i in ids))
np.savez('/tmp/zt_local.npz',**saved)
